def attacked(p, sq, by):
    if sq < 0 or sq >= 64:
        return False
    b = p.b
    r, f = divmod(sq, 8)
    rr = r - 1 if by == 0 else r + 1
    pawn = 'P' if by == 0 else 'p'
    if 0 <= rr < 8:
        for ff in (f - 1, f + 1):
            if 0 <= ff < 8 and b[rr * 8 + ff] == pawn:
                return True
    knight = 'N' if by == 0 else 'n'
    for dr, df in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
        x, y = r + dr, f + df
        if 0 <= x < 8 and 0 <= y < 8 and b[x * 8 + y] == knight:
            return True
    king = 'K' if by == 0 else 'k'
    for dr in (-1, 0, 1):
        for df in (-1, 0, 1):
            if (dr or df) and 0 <= r + dr < 8 and 0 <= f + df < 8:
                if b[(r + dr) * 8 + f + df] == king:
                    return True
    for dr, df, chars in ((1,0,'rq'),(-1,0,'rq'),(0,1,'rq'),(0,-1,'rq'),(1,1,'bq'),(1,-1,'bq'),(-1,1,'bq'),(-1,-1,'bq')):
        x, y = r + dr, f + df
        while 0 <= x < 8 and 0 <= y < 8:
            z = b[x * 8 + y]
            if z != '.':
                if z.isupper() == (by == 0) and z.lower() in chars:
                    return True
                break
            x += dr
            y += df
    return False


def king(p, side):
    target = 'K' if side == 0 else 'k'
    for i, x in enumerate(p.b):
        if x == target:
            return i
    return -1


class Position:
    def __init__(self, b, side, cast, ep, half, full):
        self.b = b
        self.side = side
        self.cast = cast
        self.ep = ep
        self.half = half
        self.full = full

    @classmethod
    def fen(cls, s):
        a = s.split()
        b = ['.'] * 64
        for ri, row in enumerate(a[0].split('/')):
            sq = (7 - ri) * 8
            for x in row:
                if x.isdigit():
                    sq += int(x)
                else:
                    b[sq] = x
                    sq += 1
        cast = 0
        for i, x in enumerate('KQkq'):
            if x in a[2]:
                cast |= 1 << i
        ep = -1
        if a[3] != '-':
            ep = ord(a[3][0]) - 97 + 8 * (int(a[3][1]) - 1)
        return cls(b, 0 if a[1] == 'w' else 1, cast, ep, int(a[4]), int(a[5]))

    @classmethod
    def start(cls):
        return cls.fen('rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1')


def enc(a, z, pr=0, fl=0):
    return a | (z << 6) | (pr << 12) | (fl << 16)


def pseudo(p, captures=False):
    b = p.b
    white = p.side == 0
    out = []

    def add(a, z, pr=0, fl=0, cap=False):
        if not captures or cap or pr:
            out.append(enc(a, z, pr, fl))

    for s, pc in enumerate(b):
        if pc == '.' or pc.isupper() != white:
            continue
        r, f = divmod(s, 8)
        t = pc.lower()
        if t == 'p':
            d = 8 if white else -8
            z = s + d
            prom = 0 <= z < 64 and z // 8 == (7 if white else 0)
            if not captures and 0 <= z < 64 and b[z] == '.':
                if prom:
                    for q in (4, 3, 2, 1):
                        add(s, z, q)
                else:
                    add(s, z)
                if r == (1 if white else 6) and b[s + d] == '.' and b[s + 2 * d] == '.':
                    add(s, s + 2 * d, 0, 4)
            for df in (-1, 1):
                if 0 <= f + df < 8:
                    z = s + d + df
                    if 0 <= z < 64:
                        x = b[z]
                        if x != '.' and x.isupper() != white:
                            if z // 8 == (7 if white else 0):
                                for q in (4, 3, 2, 1):
                                    add(s, z, q, 0, True)
                            else:
                                add(s, z, 0, 0, True)
                        elif z == p.ep:
                            add(s, z, 0, 2, True)
        elif t == 'n':
            for dr, df in ((2,1),(2,-1),(-2,1),(-2,-1),(1,2),(1,-2),(-1,2),(-1,-2)):
                x, y = r + dr, f + df
                if 0 <= x < 8 and 0 <= y < 8:
                    z = x * 8 + y
                    if b[z] == '.' or b[z].isupper() != white:
                        add(s, z, 0, 0, b[z] != '.')
        elif t in 'brq':
            dirs = []
            if t in 'bq':
                dirs += ((1,1),(1,-1),(-1,1),(-1,-1))
            if t in 'rq':
                dirs += ((1,0),(-1,0),(0,1),(0,-1))
            for dr, df in dirs:
                x, y = r + dr, f + df
                while 0 <= x < 8 and 0 <= y < 8:
                    z = x * 8 + y
                    if b[z] == '.':
                        add(s, z)
                    else:
                        if b[z].isupper() != white:
                            add(s, z, 0, 0, True)
                        break
                    x += dr
                    y += df
        else:
            for dr in (-1, 0, 1):
                for df in (-1, 0, 1):
                    if (dr or df) and 0 <= r + dr < 8 and 0 <= f + df < 8:
                        z = (r + dr) * 8 + f + df
                        if b[z] == '.' or b[z].isupper() != white:
                            add(s, z, 0, 0, b[z] != '.')
            if not captures and s == (4 if white else 60) and not attacked(p, s, p.side ^ 1):
                if white and p.cast & 1 and b[5] == b[6] == '.' and b[7] == 'R' and not attacked(p, 5, 1) and not attacked(p, 6, 1):
                    add(s, 6, 0, 1)
                if white and p.cast & 2 and b[1] == b[2] == b[3] == '.' and b[0] == 'R' and not attacked(p, 3, 1) and not attacked(p, 2, 1):
                    add(s, 2, 0, 1)
                if not white and p.cast & 4 and b[61] == b[62] == '.' and b[63] == 'r' and not attacked(p, 61, 0) and not attacked(p, 62, 0):
                    add(s, 62, 0, 1)
                if not white and p.cast & 8 and b[57] == b[58] == b[59] == '.' and b[56] == 'r' and not attacked(p, 59, 0) and not attacked(p, 58, 0):
                    add(s, 58, 0, 1)
    return out


def make(p, m):
    a = m & 63
    z = (m >> 6) & 63
    pr = (m >> 12) & 15
    fl = m >> 16
    b = p.b[:]
    pc = b[a]
    captured = b[z]
    b[a] = '.'
    if fl & 2:
        b[z + (-8 if pc.isupper() else 8)] = '.'
    b[z] = pc
    if fl & 1:
        if z == 6:
            b[5], b[7] = b[7], '.'
        elif z == 2:
            b[3], b[0] = b[0], '.'
        elif z == 62:
            b[61], b[63] = b[63], '.'
        elif z == 58:
            b[59], b[56] = b[56], '.'
    if pr:
        b[z] = ('NBRQ'[pr - 1] if pc.isupper() else 'nbrq'[pr - 1])
    c = p.cast
    if pc == 'K':
        c &= 12
    elif pc == 'k':
        c &= 3
    if a == 0 or z == 0:
        c &= ~2
    if a == 7 or z == 7:
        c &= ~1
    if a == 56 or z == 56:
        c &= ~8
    if a == 63 or z == 63:
        c &= ~4
    ep = (a + z) // 2 if pc.lower() == 'p' and abs(z - a) == 16 else -1
    is_capture = captured != '.' or bool(fl & 2)
    half = 0 if pc.lower() == 'p' or is_capture else p.half + 1
    return Position(b, p.side ^ 1, c, ep, half, p.full + (1 if p.side else 0))


def legal(p, captures=False):
    out = []
    side = p.side
    for m in pseudo(p, captures):
        if p.b[(m >> 6) & 63].lower() == 'k':
            continue
        q = make(p, m)
        kp = king(q, side)
        if kp >= 0 and not attacked(q, kp, side ^ 1):
            out.append(m)
    return out


def notation(m):
    a = m & 63
    z = (m >> 6) & 63
    pr = (m >> 12) & 15
    s = 'abcdefgh'[a & 7] + str(a // 8 + 1) + 'abcdefgh'[z & 7] + str(z // 8 + 1)
    return s + (PROM[pr] if pr else '')


class Engine:
    def __init__(self):
        self.pos = Position.start()
        self.tt = {}
        self.history = {}
        self.killers = {}
        self.nodes = 0
        self.deadline = 0

    def evaluate(self, p):
        score = 0
        phase = 0
        wp = [0] * 8
        bp = [0] * 8
        bishops_w = bishops_b = pawns = 0
        for pc in p.b:
            if pc != '.' and pc.lower() not in ('p', 'k'):
                phase += VAL[pc.lower()]
        for s, pc in enumerate(p.b):
            if pc == '.':
                continue
            typ = pc.lower()
            sg = 1 if pc.isupper() else -1
            idx = s if sg == 1 else s ^ 56
            score += sg * (VAL[typ] + PST[typ][idx])
            r, f = divmod(s, 8)
            rr = r if sg == 1 else 7 - r
            center = 7 - abs(2 * f - 7) - abs(2 * rr - 7)
            if typ == 'p':
                pawns += 1
                (wp if sg == 1 else bp)[f] += 1
                score += sg * (rr * 6 + center * 2)
                passed = True
                ranks = range(r + 1, 8) if sg == 1 else range(r - 1, -1, -1)
                enemy = 'p' if sg == 1 else 'P'
                for r2 in ranks:
                    for f2 in (f - 1, f, f + 1):
                        if 0 <= f2 < 8 and p.b[r2 * 8 + f2] == enemy:
                            passed = False
                if passed:
                    score += sg * (18 + rr * 8)
            elif typ == 'n':
                score += sg * center * 2
            elif typ == 'b':
                bishops_w += sg == 1
                bishops_b += sg == -1
            elif typ == 'r' and (wp if sg == 1 else bp)[f] == 0:
                score += sg * 14
            elif typ == 'k' and phase < 2200:
                score += sg * center * 3
        if bishops_w >= 2:
            score += 32
        if bishops_b >= 2:
            score -= 32
        for n in wp:
            score -= max(0, n - 1) * 12
        for n in bp:
            score += max(0, n - 1) * 12
        for f, n in enumerate(wp):
            if n and (f == 0 or wp[f - 1] == 0) and (f == 7 or wp[f + 1] == 0):
                score -= 10 * n
        for f, n in enumerate(bp):
            if n and (f == 0 or bp[f - 1] == 0) and (f == 7 or bp[f + 1] == 0):
                score += 10 * n
        if pawns == 0 and (phase == 0 or phase == 320 or (phase == 330 and bishops_w + bishops_b == 1)):
            return 0
        return score if p.side == 0 else -score

    def check_time(self):
        self.nodes += 1
        if (self.nodes & 15) == 0 and time.perf_counter() >= self.deadline:
            raise TimeoutError

    def mscore(self, p, m, tt, ply):
        a = m & 63
        z = (m >> 6) & 63
        pr = (m >> 12) & 15
        fl = m >> 16
        sc = 10000000 if m == tt else 0
        cap = p.b[z]
        if fl & 2:
            cap = 'p'
        if cap != '.':
            sc += 1000000 + VAL[cap.lower()] * 10 - VAL[p.b[a].lower()]
        if pr:
            sc += 800000 + pr * 10000
        if self.killers.get(ply) == m:
            sc += 500000
        sc += self.history.get((p.side, a, z), 0)
        if fl & 1:
            sc += 100
        return sc

    def qsearch(self, p, alpha, beta, ply):
        self.check_time()
        checked = attacked(p, king(p, p.side), p.side ^ 1)
        if not checked:
            stand = self.evaluate(p)
            if stand >= beta:
                return stand
            if stand > alpha:
                alpha = stand
        if ply >= 10:
            ms = legal(p)
            if not ms:
                return -MATE + ply if checked else 0
            return self.evaluate(p)
        ms = legal(p, False if checked else True)
        if not ms:
            return -MATE + ply if checked else 0
        ms.sort(key=lambda m: self.mscore(p, m, -1, ply), reverse=True)
        for m in ms:
            sc = -self.qsearch(make(p, m), -beta, -alpha, ply + 1)
            if sc >= beta:
                return sc
            if sc > alpha:
                alpha = sc
        return alpha

    def search(self, p, depth, alpha, beta, ply, allow_tt=True):
        self.check_time()
        if depth <= 0:
            return self.qsearch(p, alpha, beta, ply)
        key = (''.join(p.b), p.side, p.cast, p.ep, p.half, p.full)
        orig = alpha
        oldbeta = beta
        ttmove = -1
        ent = self.tt.get(key) if allow_tt else None
        if ent:
            ttdepth, ttscore, flag, ttmove = ent
            if ttdepth >= depth:
                if flag == 0:
                    return ttscore
                if flag == 1:
                    alpha = max(alpha, ttscore)
                else:
                    beta = min(beta, ttscore)
                if alpha >= beta:
                    return ttscore
        ms = legal(p)
        if not ms:
            return -MATE + ply if attacked(p, king(p, p.side), p.side ^ 1) else 0
        ms.sort(key=lambda m: self.mscore(p, m, ttmove, ply), reverse=True)
        best = -INF
        bestm = ms[0]
        for m in ms:
            q = make(p, m)
            nd = depth - 1
            if depth <= 2 and attacked(q, king(q, q.side), q.side ^ 1):
                nd += 1
            sc = -self.search(q, nd, -beta, -alpha, ply + 1)
            if sc > best:
                best = sc
                bestm = m
            if sc > alpha:
                alpha = sc
            if alpha >= beta:
                if p.b[m & 63].lower() != 'p' and p.b[(m >> 6) & 63] == '.' and not ((m >> 12) & 15):
                    self.killers[ply] = m
                    hkey = (p.side, m & 63, (m >> 6) & 63)
                    self.history[hkey] = min(10000, self.history.get(hkey, 0) + depth * depth)
                break
        flag = 2 if best <= orig else 1 if best >= oldbeta else 0
        self.tt[key] = (depth, best, flag, bestm)
        if len(self.tt) > 160000:
            self.tt.clear()
        return best

    def root(self, p, ms, depth):
        ms = ms[:]
        ms.sort(key=lambda m: self.mscore(p, m, -1, 0), reverse=True)
        best = -INF
        bm = ms[0]
        for m in ms:
            self.check_time()
            sc = -self.search(make(p, m), depth - 1, -INF, INF, 1, False)
            if sc > best:
                best = sc
                bm = m
        return best, bm

    def think(self, millis):
        self.deadline = time.perf_counter() + max(0.0005, millis / 1000.0 * 0.76)
        moves = legal(self.pos)
        if not moves:
            return '0000'
        best = moves[0]
        if millis <= 5:
            return notation(best)
        self.nodes = 0
        for depth in range(1, 64):
            try:
                score, move = self.root(self.pos, moves, depth)
            except TimeoutError:
                break
            best = move
            if abs(score) > MATE - 1000:
                break
        return notation(best)

    def setpos(self, a):
        if len(a) > 1 and a[1] == 'startpos':
            p = Position.start()
            i = 2
        elif len(a) >= 8 and a[1] == 'fen':
            p = Position.fen(' '.join(a[2:8]))
            i = 8
        else:
            return
        if i < len(a) and a[i] == 'moves':
            for u in a[i + 1:]:
                for m in legal(p):
                    if notation(m) == u:
                        p = make(p, m)
                        break
        self.pos = p


